mapper.select:
/* com.portal.security.role.RoleManageMapper.selectRoleList */ SELECT ROLE_CODE AS roleCode, ROLE_NM AS roleNm, ROLE_PTTRN AS rolePtn, ROLE_DC AS roleDc, ( SELECT c.CODE_NM FROM LETTCCMMNDETAILCODE c WHERE c.CODE_ID = 'COM029' AND c.CODE = ROLE_TY ) AS roleTyp, ROLE_SORT AS roleSort, ROLE_CREAT_DE AS roleCreatDe FROM LETTNROLEINFO WHERE 1 = 1
AND ROLE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY ROLE_CREAT_DE DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}
